<script setup lang="ts">
import {ref,reactive,watch,onBeforeUnmount} from 'vue';
import {get,write} from '../../../../packages/shared/src/client';
import {useTask,money,query,type Row} from '../../../../packages/shared/src/ui';
import Status from '../../../../packages/shared/src/Status.vue';
const task=useTask(),service=ref('trade'),identifier=ref(''),errorCode=ref('');
const services=['auth','trade','learning','promotion','exam','search','remark','message','user','course','media','pay'];
type FailureKind='operations'|'events'|'failures';
const sections:{kind:FailureKind;title:string;endpoint:string}[]=[{kind:'operations',title:'业务请求失败',endpoint:'operation-failures'},{kind:'events',title:'投递失败任务',endpoint:'events'},{kind:'failures',title:'消费失败任务',endpoint:'consumer-failures'}];
const pages=reactive<Record<FailureKind,{rows:Row[];page:number;total:number;busy:boolean;error:string;revision:number}>>({operations:{rows:[],page:1,total:0,busy:false,error:'',revision:0},events:{rows:[],page:1,total:0,busy:false,error:'',revision:0},failures:{rows:[],page:1,total:0,busy:false,error:'',revision:0}});
async function loadPage(kind:FailureKind){
 const state=pages[kind],revision=++state.revision,source=service.value;
 state.rows=[];state.total=0;state.busy=true;state.error='';
 if(kind==='failures'&&source==='media'){state.busy=false;return;}
 const endpoint=sections.find(s=>s.kind===kind)!.endpoint;
 try{const result=await get<Row>('/admin/'+endpoint+'/'+source+'/page?'+query({pageNo:state.page,pageSize:20,identifier:identifier.value.trim(),errorCode:kind==='operations'?errorCode.value:undefined}));
 if(revision!==state.revision||source!==service.value)return;
 state.rows=(result.list||[]).map((row:Row)=>({...row,sourceService:source}));state.total=Number(result.total||0);
 if(!state.rows.length&&state.page>1&&state.total<=(state.page-1)*20){state.page=Math.max(1,Math.ceil(state.total/20));void loadPage(kind);}
 }catch(error){if(revision===state.revision&&source===service.value)state.error=error instanceof Error?error.message:'请求失败';}
 finally{if(revision===state.revision)state.busy=false;}
}
function loadFailures(){for(const section of sections){pages[section.kind].page=1;void loadPage(section.kind);}}
watch(service,loadFailures);
onBeforeUnmount(()=>{for(const section of sections)pages[section.kind].revision++;});
const conflicts=ref<Row[]>([]),compensationKind=ref('payment'),compensations=ref<Row[]>([]),conflictTask=useTask(),compensationTask=useTask();
const deliveryKind=ref('notice'),deliveries=ref<Row[]>([]),deliveryTask=useTask(),cleanups=ref<Row[]>([]),metadata=ref<Row[]>([]),storageTask=useTask(),projectionTask=useTask();
const providerAnomalies=ref<Row[]>([]),providerReconciliations=ref<Row[]>([]),anomalyStatus=ref('OPEN'),reconciliationStatus=ref('DEAD'),anomalyTask=useTask(),reconciliationTask=useTask();
const resolution=ref(''),selected=ref<Row>(),selectedKind=ref<'conflict'|'providerAnomaly'|'providerReplay'>('conflict');
let compensationRevision=0,deliveryRevision=0,anomalyRevision=0,reconciliationRevision=0;
async function loadConflicts(){if(conflictTask.busy.value)return;conflicts.value=[];await conflictTask.run(async()=>{conflicts.value=await get<Row[]>('/admin/payment-conflicts');});}
async function loadCompensations(){if(compensationTask.busy.value)return;const source=compensationKind.value,revision=++compensationRevision;compensations.value=[];await compensationTask.run(async()=>{const data=await get<Row[]>('/admin/compensations/'+source);if(revision===compensationRevision&&source===compensationKind.value)compensations.value=data.map(row=>({...row,sourceKind:source}));});}
watch(compensationKind,()=>{compensations.value=[];});
function load(){loadFailures();void loadConflicts();void loadCompensations();}
async function replayFailure(row:Row,kind:FailureKind){const source=row.sourceService;if(source!==service.value)return;
 const endpoint=sections.find(s=>s.kind===kind)!.endpoint,id=kind==='operations'?row.operation_id:kind==='events'?row.event_id:row.failure_id;
 const ok=await task.run(async()=>{await write('/admin/'+endpoint+'/'+source+'/'+encodeURIComponent(id)+'/replay'+(kind==='events'?'':'?version='+row.version),'POST');return true;});
 if(ok){if(source===service.value)await loadPage(kind);task.message.value='已安排重试，请核对刷新后的真实状态；事件 ID 保持不变';}}
async function replayCompensation(row:Row){const source=row.sourceKind;const ok=await task.run(async()=>{await write('/admin/compensations/'+source+'/'+(row.refund_id??row.order_id)+'/replay?version='+row.version,'POST');return true;});if(ok){await loadCompensations();task.message.value='已安排补偿重试';}}
async function loadDeliveries(){if(deliveryTask.busy.value)return;const source=deliveryKind.value,revision=++deliveryRevision;deliveries.value=[];await deliveryTask.run(async()=>{const data=await get<Row[]>('/admin/deliveries/'+source);if(revision===deliveryRevision&&source===deliveryKind.value)deliveries.value=data.map(row=>({...row,sourceKind:source}));});}
watch(deliveryKind,()=>{deliveries.value=[];});
async function replayDelivery(row:Row){const ok=await task.run(async()=>{await write('/admin/deliveries/'+row.sourceKind+'/'+row.id+'/replay?version='+row.version,'POST');return true;});if(ok)await loadDeliveries();}
async function loadStorage(){if(storageTask.busy.value)return;cleanups.value=[];await storageTask.run(async()=>{cleanups.value=await get<Row[]>('/admin/storage-cleanups');});}
async function loadSearch(){if(projectionTask.busy.value)return;metadata.value=[];await projectionTask.run(async()=>{metadata.value=await get<Row[]>('/admin/search-projections');});}
function loadProjections(){void loadStorage();void loadSearch();}
async function replayProjection(row:Row,storage:boolean){const ok=await task.run(async()=>{await write((storage?'/admin/storage-cleanups/':'/admin/search-projections/')+(row.id??row.course_id)+'/replay?version='+row.version+(storage?'':'&kind='+row.kind),'POST');return true;});if(ok){if(storage)await loadStorage();else await loadSearch();}}
async function loadAnomalies(){if(anomalyTask.busy.value)return;const source=anomalyStatus.value,revision=++anomalyRevision;providerAnomalies.value=[];await anomalyTask.run(async()=>{const data=await get<Row[]>('/admin/provider-payments/anomalies?status='+source);if(revision===anomalyRevision&&source===anomalyStatus.value)providerAnomalies.value=data;});}
async function loadReconciliations(){if(reconciliationTask.busy.value)return;const source=reconciliationStatus.value,revision=++reconciliationRevision;providerReconciliations.value=[];await reconciliationTask.run(async()=>{const data=await get<Row[]>('/admin/provider-payments/reconciliations?status='+source);if(revision===reconciliationRevision&&source===reconciliationStatus.value)providerReconciliations.value=data;});}
watch(anomalyStatus,()=>{providerAnomalies.value=[];});watch(reconciliationStatus,()=>{providerReconciliations.value=[];});
function loadProviderPayments(){void loadAnomalies();void loadReconciliations();}
function openResolution(row:Row,kind:'conflict'|'providerAnomaly'|'providerReplay'){selected.value=row;selectedKind.value=kind;resolution.value='';task.error.value='';}
async function resolve(){const kind=selectedKind.value;const ok=await task.run(async()=>{if(!selected.value)return;const row=selected.value,body={version:row.version,resolution:resolution.value.trim()};if(kind==='providerAnomaly')await write('/admin/provider-payments/anomalies/'+encodeURIComponent(row.pay_order_no)+'/'+encodeURIComponent(row.reason),'PUT',body);else if(kind==='providerReplay')await write('/admin/provider-payments/reconciliations/'+encodeURIComponent(row.pay_order_no)+'/replay','POST',body);else await write('/admin/payment-conflicts/'+row.id,'PUT',body);selected.value=undefined;return true;});if(ok){if(kind==='conflict')await loadConflicts();else loadProviderPayments();task.message.value=kind==='providerReplay'?'重新核对已安排，处理依据已记录':'人工处理依据已记录';}}
</script>
<template><section class="card reliability-page"><h2>事件与业务冲突处理</h2><div class="toolbar"><el-select v-model="service" aria-label="故障模块" style="width:180px"><el-option v-for="s in services" :key="s" :value="s" :label="s"/></el-select><el-input v-model="identifier" aria-label="故障标识" placeholder="精确查询操作、事件或业务标识" clearable @keyup.enter="loadFailures"/><el-button @click="load">查询服务</el-button></div><Status :busy="task.busy.value" :error="task.error.value" :message="task.message.value"/><p class="muted">版本冲突时请重新查询并核对后处理。普通业务校验失败需要修正请求。</p>
<section v-for="section in sections" :key="section.kind" :aria-label="section.title"><div class="section-heading"><h3>{{section.title}} · {{service}}</h3><el-button @click="loadPage(section.kind)" :disabled="pages[section.kind].busy||(section.kind==='failures'&&service==='media')">{{'刷新'+section.title}}</el-button></div><template v-if="section.kind==='operations'"><el-select v-model="errorCode" aria-label="业务失败类型" clearable placeholder="全部失败类型" @change="pages.operations.page=1;loadPage('operations')"><el-option value="RETRY_EXHAUSTED" label="临时故障重试耗尽"/><el-option value="BUSINESS_FAILED" label="业务校验失败"/></el-select></template><Status :busy="pages[section.kind].busy" :error="pages[section.kind].error"/><p v-if="section.kind==='failures'&&service==='media'" class="muted">该模块无消息消费任务。</p><el-table :data="pages[section.kind].rows"><el-table-column prop="sourceService" label="来源模块" width="110"/><el-table-column v-if="section.kind==='operations'" prop="operation_id" label="操作 ID" min-width="180"/><el-table-column v-else prop="event_id" label="事件 ID" min-width="180"/><el-table-column v-if="section.kind==='operations'" prop="kind" label="类型"/><el-table-column v-if="section.kind==='events'" prop="business_key" label="业务标识"/><el-table-column v-if="section.kind==='failures'" prop="queue_name" label="消费队列"/><el-table-column prop="last_error" label="失败原因" min-width="180"/><el-table-column label="操作" min-width="150"><template #default="{row}"><el-button v-if="section.kind!=='operations'||row.error_code==='RETRY_EXHAUSTED'" @click="replayFailure(row,section.kind)" :disabled="task.busy.value||pages[section.kind].busy">{{section.kind==='operations'?'重试临时故障':'重放'}}</el-button><span v-else>业务校验失败，请修正请求</span></template></el-table-column></el-table><el-pagination v-if="pages[section.kind].total>20" v-model:current-page="pages[section.kind].page" :total="pages[section.kind].total" :page-size="20" :disabled="pages[section.kind].busy" layout="total,prev,pager,next" @current-change="loadPage(section.kind)"/></section>
<section aria-label="持久补偿任务"><h3>持久补偿任务</h3><div class="toolbar"><el-select v-model="compensationKind" aria-label="补偿类型" :disabled="compensationTask.busy.value" @change="loadCompensations"><el-option value="payment" label="支付核对"/><el-option value="refund" label="退款发送"/></el-select><el-button @click="loadCompensations" :disabled="compensationTask.busy.value">刷新补偿任务</el-button></div><Status :busy="compensationTask.busy.value" :error="compensationTask.error.value"/><el-table :data="compensations"><el-table-column label="业务 ID"><template #default="{row}">{{row.refund_id??row.order_id}}</template></el-table-column><el-table-column prop="status" label="状态"/><el-table-column prop="attempts" label="尝试次数"/><el-table-column prop="last_error" label="失败原因"/><el-table-column label="操作"><template #default="{row}"><el-button v-if="row.status==='DEAD'" @click="replayCompensation(row)" :disabled="task.busy.value">重试失败任务</el-button></template></el-table-column></el-table></section>
<section aria-label="通知发送任务"><h3>通知发送任务</h3><div class="toolbar"><el-select v-model="deliveryKind" :disabled="deliveryTask.busy.value"><el-option value="notice" label="站内通知"/><el-option value="sms" label="短信发送"/></el-select><el-button @click="loadDeliveries" :disabled="deliveryTask.busy.value">查询通知任务</el-button></div><Status :busy="deliveryTask.busy.value" :error="deliveryTask.error.value"/><el-table :data="deliveries"><el-table-column prop="id" label="任务 ID"/><el-table-column prop="status" label="状态"/><el-table-column prop="last_error" label="失败原因"/><el-table-column label="操作"><template #default="{row}"><el-button v-if="row.status==='DEAD'" @click="replayDelivery(row)" :disabled="task.busy.value">重试失败任务</el-button></template></el-table-column></el-table></section>
<h3>资源删除与搜索投影</h3><el-button @click="loadProjections">查询资源与搜索任务</el-button><Status :busy="storageTask.busy.value" :error="storageTask.error.value"/><el-button v-if="storageTask.error.value" @click="loadStorage">重试资源删除查询</el-button><Status :busy="projectionTask.busy.value" :error="projectionTask.error.value"/><el-button v-if="projectionTask.error.value" @click="loadSearch">重试搜索投影查询</el-button><el-table :data="[...cleanups.map(x=>({...x,storage:true})),...metadata.map(x=>({...x,storage:false}))]"><el-table-column label="业务 ID"><template #default="{row}">{{row.id??row.course_id}}</template></el-table-column><el-table-column prop="status" label="状态"/><el-table-column prop="last_error" label="失败原因"/><el-table-column label="操作"><template #default="{row}"><el-button v-if="row.status==='DEAD'" @click="replayProjection(row,row.storage)" :disabled="task.busy.value">重试失败任务</el-button></template></el-table-column></el-table>
<h3>支付渠道异常与核对任务</h3><p>核对渠道账单后记录处理依据。记录异常处理不会自动恢复订单、发课或退款；失败任务重试会重新查询支付渠道。</p><div class="toolbar"><el-select v-model="anomalyStatus" aria-label="渠道异常状态" :disabled="anomalyTask.busy.value"><el-option value="OPEN" label="待处理异常"/><el-option value="RESOLVED" label="已处理异常"/></el-select><el-select v-model="reconciliationStatus" aria-label="渠道核对任务状态" :disabled="reconciliationTask.busy.value"><el-option value="DEAD" label="待人工核对"/><el-option value="PENDING" label="等待核对"/><el-option value="SENDING" label="核对中"/><el-option value="DONE" label="核对完成"/></el-select><el-button @click="loadProviderPayments" :disabled="anomalyTask.busy.value||reconciliationTask.busy.value">查询渠道异常与核对任务</el-button></div><small>渠道列表显示最近 100 条。版本已变化时请关闭对话框并重新查询、核对后再处理。</small><Status :busy="anomalyTask.busy.value" :error="anomalyTask.error.value"/><el-button v-if="anomalyTask.error.value" @click="loadAnomalies">重试渠道异常查询</el-button><el-table :data="providerAnomalies"><el-table-column prop="pay_order_no" label="支付单号"/><el-table-column prop="reason" label="异常原因"/><el-table-column label="金额核对"><template #default="{row}">应付 {{row.expected_amount==null?'未知':money(row.expected_amount)}} / 渠道 {{row.observed_amount==null?'未返回':money(row.observed_amount)}}</template></el-table-column><el-table-column prop="observed_order_no" label="渠道返回单号"/><el-table-column prop="observed_time" label="渠道支付时间"/><el-table-column prop="status" label="状态"/><el-table-column prop="last_seen_at" label="最近发现"/><el-table-column prop="resolution" label="处理依据"/><el-table-column label="操作"><template #default="{row}"><el-button v-if="row.status==='OPEN'" @click="openResolution(row,'providerAnomaly')" :disabled="task.busy.value">记录异常处理</el-button></template></el-table-column></el-table>
<Status :busy="reconciliationTask.busy.value" :error="reconciliationTask.error.value"/><el-button v-if="reconciliationTask.error.value" @click="loadReconciliations">重试渠道核对查询</el-button><el-table :data="providerReconciliations"><el-table-column prop="pay_order_no" label="支付单号"/><el-table-column prop="status" label="核对状态"/><el-table-column prop="attempts" label="尝试次数"/><el-table-column prop="next_attempt_at" label="下次核对"/><el-table-column prop="last_error" label="失败原因"/><el-table-column label="操作"><template #default="{row}"><el-button v-if="row.status==='DEAD'" @click="openResolution(row,'providerReplay')" :disabled="task.busy.value">记录依据并重试核对</el-button></template></el-table-column></el-table>
<section aria-label="支付冲突工单"><h3>支付冲突工单</h3><p>取消后到账的支付事实保留在工单中。确认处理依据不会自动恢复订单、发课或退款。</p><el-button @click="loadConflicts" :disabled="conflictTask.busy.value">刷新支付冲突</el-button><Status :busy="conflictTask.busy.value" :error="conflictTask.error.value"/><el-table :data="conflicts"><el-table-column prop="order_id" label="订单 ID"/><el-table-column prop="pay_order_no" label="支付单号"/><el-table-column prop="reason" label="冲突原因"/><el-table-column label="操作"><template #default="{row}"><el-button @click="openResolution(row,'conflict')" :disabled="task.busy.value">记录人工处理</el-button></template></el-table-column></el-table></section>
<el-dialog :model-value="!!selected" @update:model-value="(value:boolean)=>{if(!value)selected=undefined;}" :title="selectedKind==='providerReplay'?'记录重新核对依据':'记录人工处理依据'"><Status :busy="task.busy.value" :error="task.error.value"/><p v-if="selectedKind!=='conflict'">支付单号：{{selected?.pay_order_no}}<template v-if="selectedKind==='providerAnomaly'"> · {{selected?.reason}}</template></p><el-input v-model="resolution" type="textarea" :rows="6" maxlength="2000"/><template #footer><el-button type="primary" @click="resolve" :disabled="!resolution.trim()||task.busy.value">{{selectedKind==='providerReplay'?'保存依据并重试核对':'保存处理记录'}}</el-button></template></el-dialog>
</section></template>
<style scoped>.reliability-page>.toolbar .el-input{max-width:360px}.reliability-page section{margin:1.5rem 0}.reliability-page .el-pagination{max-width:100%;overflow-x:auto}</style>
